6	+package copilotcli
7	+
8	+import (
9	+	"encoding/json"
10	+	"errors"
11	+	"fmt"
12	+	"time"
13	+)
14	+
15	+// HookHost identifies which host format produced a copilot-compatible hook payload.
16	+type HookHost string
17	+
18	+const (
19	+	HostUnknown    HookHost = "unknown"
20	+	HostCopilotCLI HookHost = "copilot-cli"
21	+	HostVSCode     HookHost = "vscode"
22	+)
23	+
24	+// VS Code hookEventName values (from official VS Code docs).
25	+// See: https://code.visualstudio.com/docs/copilot/customization/hooks
26	+const (
27	+	VSCodeEventSessionStart     = "SessionStart"
28	+	VSCodeEventUserPromptSubmit = "UserPromptSubmit"
29	+	VSCodeEventStop             = "Stop"
30	+	VSCodeEventPreToolUse       = "PreToolUse"
31	+	VSCodeEventPostToolUse      = "PostToolUse"
32	+	VSCodeEventPreCompact       = "PreCompact"
33	+	VSCodeEventSubagentStart    = "SubagentStart"
34	+	VSCodeEventSubagentStop     = "SubagentStop"
35	+)
36	+
37	+// vsCodeEventToHookNames maps each VS Code hookEventName to the CLI hook name(s)
38	+// that are allowed to carry that event. "Stop" maps to both agent-stop and
39	+// session-end because VS Code uses a single Stop event where Copilot CLI
40	+// distinguishes the two.
41	+var vsCodeEventToHookNames = map[string][]string{
42	+	VSCodeEventUserPromptSubmit: {HookNameUserPromptSubmitted},
43	+	VSCodeEventSessionStart:     {HookNameSessionStart},
44	+	VSCodeEventStop:             {HookNameAgentStop, HookNameSessionEnd},
45	+	VSCodeEventSubagentStop:     {HookNameSubagentStop},
46	+	VSCodeEventPreToolUse:       {HookNamePreToolUse},
47	+	VSCodeEventPostToolUse:      {HookNamePostToolUse},
48	+	VSCodeEventPreCompact:       {},
49	+	VSCodeEventSubagentStart:    {},
50	+}
51	+
52	+type hookEnvelope struct {
53	+	Host           HookHost
54	+	SessionID      string
55	+	Prompt         string
56	+	TranscriptPath string
57	+	HookEventName  string
58	+	Source         string
59	+	InitialPrompt  string
60	+	StopReason     string
61	+	Reason         string
62	+	Timestamp      time.Time
63	+}
64	+
65	+func parseHookEnvelope(data []byte) (*hookEnvelope, error) {
66	+	if len(data) == 0 {
67	+		return nil, errors.New("empty hook input")
68	+	}
69	+
70	+	var raw map[string]json.RawMessage
71	+	if err := json.Unmarshal(data, &raw); err != nil {
72	+		return nil, fmt.Errorf("failed to parse hook input: %w", err)
73	+	}
74	+
75	+	env := &hookEnvelope{
76	+		Host:           detectHookHost(raw),
77	+		SessionID:      firstString(raw, "sessionId"),
78	+		Prompt:         firstString(raw, "prompt"),
79	+		TranscriptPath: firstString(raw, "transcriptPath", "transcript_path"),
80	+		HookEventName:  firstString(raw, "hookEventName"),
81	+		Source:         firstString(raw, "source"),
82	+		InitialPrompt:  firstString(raw, "initialPrompt"),
83	+		StopReason:     firstString(raw, "stopReason"),
84	+		Reason:         firstString(raw, "reason"),
85	+	}
86	+
87	+	ts, err := parseTimestamp(raw["timestamp"])
88	+	if err != nil {
89	+		return nil, fmt.Errorf("failed to parse hook input: %w", err)
90	+	}
91	+	env.Timestamp = ts
92	+
93	+	if env.Timestamp.IsZero() {
94	+		env.Timestamp = time.Now()
95	+	}
96	+
97	+	return env, nil
98	+}
99	+
100	+func detectHookHost(raw map[string]json.RawMessage) HookHost {
101	+	if _, ok := raw["hookEventName"]; ok {
102	+		return HostVSCode
103	+	}
104	+	if _, ok := raw["transcript_path"]; ok {
105	+		return HostVSCode
106	+	}
107	+	if isJSONString(raw["timestamp"]) {
108	+		return HostVSCode
109	+	}
110	+	if _, ok := raw["transcriptPath"]; ok {
111	+		return HostCopilotCLI
112	+	}
113	+	if isJSONNumber(raw["timestamp"]) {
114	+		return HostCopilotCLI
115	+	}
116	+	return HostUnknown
117	+}
118	+
119	+func firstString(raw map[string]json.RawMessage, keys ...string) string {
120	+	for _, key := range keys {
121	+		value, ok := raw[key]
122	+		if !ok {
123	+			continue
124	+		}
125	+		var s string
126	+		if err := json.Unmarshal(value, &s); err == nil {
127	+			return s
128	+		}
129	+	}
130	+	return ""
131	+}
132	+
133	+func parseTimestamp(raw json.RawMessage) (time.Time, error) {
134	+	if len(raw) == 0 || string(raw) == "null" {
135	+		return time.Time{}, nil
136	+	}
137	+
138	+	var millis int64
139	+	if err := json.Unmarshal(raw, &millis); err == nil {
140	+		if millis == 0 {
141	+			return time.Time{}, nil // Treat epoch as missing — triggers time.Now() fallback.
142	+		}
143	+		return time.UnixMilli(millis), nil
144	+	}
145	+
146	+	var ts string
147	+	if err := json.Unmarshal(raw, &ts); err != nil {
148	+		return time.Time{}, fmt.Errorf("unmarshal timestamp string: %w", err)
149	+	}
150	+
151	+	parsed, err := time.Parse(time.RFC3339Nano, ts)
152	+	if err != nil {
153	+		return time.Time{}, fmt.Errorf("parse timestamp %q: %w", ts, err)
154	+	}
155	+	return parsed, nil
156	+}
157	+
158	+func isJSONString(raw json.RawMessage) bool {
159	+	if len(raw) == 0 || raw[0] != '"' {
160	+		return false
161	+	}
162	+	var s string
163	+	return json.Unmarshal(raw, &s) == nil
164	+}
165	+
166	+func isJSONNumber(raw json.RawMessage) bool {
167	+	if len(raw) == 0 || raw[0] == 'n' {
168	+		return false
169	+	}
170	+	var n int64
171	+	return json.Unmarshal(raw, &n) == nil
172	+}
173	+
174	+// validateVSCodeEvent checks whether the hookEventName is consistent with the
175	+// CLI hook subcommand that was invoked. Returns true if the event should be
176	+// processed, false if it should be silently skipped (mismatch or unknown event).
177	+func validateVSCodeEvent(hookEventName, hookName string) bool {
178	+	allowedHooks, known := vsCodeEventToHookNames[hookEventName]
179	+	if !known {
180	+		return false
181	+	}
182	+	for _, allowed := range allowedHooks {
183	+		if allowed == hookName {
184	+			return true
185	+		}
186	+	}
187	+	return false
188	+}
